<?php require_once __DIR__ . '/../cdn.php'; $defaultConfig = include __DIR__ . '/../config.default.php'; $statsDir = $defaultConfig['stats_dir'] ?? (__DIR__ . '/../stats'); \SimpleCdn\lib\Region::initStorage($statsDir); $message = ''; $msgType = 'ok'; $clientIp = \SimpleCdn\lib\Region::getClientIp(); if ($_SERVER['REQUEST_METHOD'] === 'POST') { $do = $_POST['do'] ?? ''; switch ($do) { case 'save_source': $origin = trim($_POST['origin'] ?? ''); $file = $statsDir . '/cdn_source.json'; @file_put_contents($file, json_encode(['origin' => $origin, 'updated_at' => time()], JSON_UNESCAPED_UNICODE)); $message = '源站地址已保存'; break; case 'add_region': $region = trim($_POST['region'] ?? ''); $origin = trim($_POST['origin'] ?? ''); if ($region !== '' && $origin !== '') { \SimpleCdn\lib\Region::setRegionOrigin($region, $origin); $message = '地区映射已添加：' . htmlspecialchars($region); } else { $message = '地区和源站/资源均不能为空'; $msgType = 'warn'; } break; case 'del_region': $region = $_POST['region'] ?? ''; if ($region !== '') { \SimpleCdn\lib\Region::removeRegionOrigin($region); $message = '已删除地区映射：' . htmlspecialchars($region); } break; case 'clear_all_cache': $deleted = \SimpleCdn\Cdn::clearCache(); $message = '已清理全部站点缓存，删除了 ' . number_format($deleted) . ' 个缓存文件'; break; } if ($message !== '') { $uri = $_SERVER['REQUEST_URI'] ?? 'source.php'; $sep = (strpos($uri, '?') === false) ? '?' : '&'; header('Location: source.php' . $sep . 'msg=' . urlencode($message) . ($msgType === 'warn' ? '&type=warn' : '')); exit; } } $msg = $_GET['msg'] ?? ''; $msgType = (($_GET['type'] ?? '') === 'warn') ? 'warn' : 'ok'; $customSourceFile = $statsDir . '/cdn_source.json'; $customSource = []; if (is_file($customSourceFile)) { $customSource = json_decode(@file_get_contents($customSourceFile), true) ?: []; } $originConfigured = $defaultConfig['origin'] ?? ''; $originShow = $customSource['origin'] ?? $originConfigured; $regionMap = \SimpleCdn\lib\Region::loadRegionMap(); $detectIp = ''; $detectRegion = ''; $detectOrigin = ''; if (($_GET['do'] ?? '') === 'detect' && isset($_GET['ip'])) { $detectIp = trim($_GET['ip']); $detectRegion = \SimpleCdn\lib\Region::detectRegion($detectIp); $detectOrigin = \SimpleCdn\lib\Region::getRegionOrigin($detectRegion); $detectOrigin = $detectOrigin ?: '(未配置，回退默认源站)'; if ($detectRegion !== '' && $detectRegion !== '--') { \SimpleCdn\lib\Region::recordHit($detectRegion, $detectIp); } } $testUrl = ''; $testStatus = null; $testTimeMs = null; $testHeaders = []; $testError = ''; if (($_GET['do'] ?? '') === 'test_origin' && isset($_GET['url'])) { $testUrl = trim($_GET['url']); if ($testUrl !== '') { $start = microtime(true); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $testUrl); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_HEADER, true); curl_setopt($ch, CURLOPT_TIMEOUT, 15); curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true); curl_setopt($ch, CURLOPT_NOBODY, true); $raw = curl_exec($ch); $end = microtime(true); if ($raw === false) { $testError = curl_error($ch); $testStatus = 0; } else { $testStatus = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE); $testTimeMs = round(($end - $start) * 1000); $headerSize = (int) curl_getinfo($ch, CURLINFO_HEADER_SIZE); $rawHeaders = substr($raw, 0, $headerSize); foreach (preg_split("/\r\n|\n|\r/", $rawHeaders) as $line) { $line = trim($line); if ($line === '' || stripos($line, 'HTTP/') === 0) { continue; } $pos = strpos($line, ':'); if ($pos !== false) { $testHeaders[trim(substr($line, 0, $pos))] = trim(substr($line, $pos + 1)); } } } @curl_close($ch); } } $hits = array_slice(\SimpleCdn\lib\Region::loadHits(), 0, 20); ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 源码对接 / 源站管理</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .topbar .user { font-size: 13px; color: #64748b; } .container { max-width: 1100px; margin: 24px auto; padding: 0 20px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 24px; margin-bottom: 20px; } .card h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; display: flex; align-items: center; gap: 8px; } .msg { padding: 12px 16px; border-radius: 6px; margin-bottom: 16px; font-size: 14px; } .msg.ok { background: #dcfce7; color: #166534; border: 1px solid #86efac; } .msg.warn { background: #fef3c7; color: #92400e; border: 1px solid #fde68a; } .btn { display: inline-block; padding: 10px 18px; background: #2563eb; color: #fff; border: none; border-radius: 6px; font-size: 14px; cursor: pointer; text-decoration: none; } .btn:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-danger { background: #dc2626; } .btn-danger:hover { background: #b91c1c; } .btn-sm { padding: 6px 12px; font-size: 12px; } label { display: block; font-size: 13px; color: #64748b; margin-bottom: 6px; } input[type=text], input[type=url], select { width: 100%; padding: 10px; border: 1px solid #e2e8f0; border-radius: 6px; font-size: 14px; box-sizing: border-box; margin-bottom: 14px; } .row { display: flex; gap: 12px; flex-wrap: wrap; } .row > * { flex: 1 1 220px; } .kv { font-size: 13px; color: #64748b; margin-bottom: 16px; } .kv b { color: #111; } .table { width: 100%; border-collapse: collapse; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-cdn { background: #dbeafe; color: #1e40af; } .badge-unk { background: #e2e8f0; color: #475569; } .empty { color: #94a3b8; font-style: italic; } .muted { color: #64748b; font-size: 13px; margin-top: 12px; } .hint { font-size: 12px; color: #64748b; margin-top: 8px; } pre { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; font-size: 12px; overflow-x: auto; margin: 10px 0; } .grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 16px; } .stat { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 16px; } .stat .v { font-size: 26px; font-weight: 700; color: #0f172a; } .stat .l { font-size: 13px; color: #64748b; margin-top: 6px; } </style> </head> <body> <div class="topbar"> <h1>源码对接 / 源站管理</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary btn-sm">← 返回仪表盘</a> <a href="action.php?do=logout" class="btn-danger btn-sm" style="padding:6px 12px;">退出登录</a> </div> <div class="container"> if ($msg): ?> <div class="msg echo $msgType; ?>">echo htmlspecialchars($msg); ?></div> endif; ?> <!-- 卡片 1：源站配置 --> <div class="card"> <h2>🔧 源站（Origin）配置</h2> <p class="muted">填写主站（万能资料库等）的网站地址，作为 CDN 回源站点。留空表示未配置，回源时将使用默认规则。</p> <div class="kv"><b>配置文件 origin：</b>echo htmlspecialchars($originConfigured ?: '(未配置)'); ?></div> <div class="kv"><b>当前生效：</b>echo htmlspecialchars($originShow ?: '(未配置)'); ?></div> <form method="POST" action="" style="margin-top:16px;"> <input type="hidden" name="do" value="save_source"> <label>源站地址（Origin URL，例如 https://zikan.zyfx.wang）</label> <input type="url" name="origin" value="echo htmlspecialchars($customSource['origin'] ?? ''); ?>" placeholder="留空则不强制指定"> <button type="submit" class="btn">保存源站地址</button> </form> <div class="hint">保存后写入 stats/cdn_source.json，不改动数据库；也可直接在 config.php 的 origin 字段填写。</div> </div> <!-- 卡片 2：地区 - 源站/资源 映射 --> <div class="card"> <h2>🗺️ 地区 - 源站/资源 映射</h2> <p class="muted">按访客地区自主判断资源切换。首个访问某地区的访客，由 IP 判定地区并记录映射；下次同地区直接调用该地区对应的源站/资源。</p> <div class="row" style="margin-bottom:16px;"> <form method="POST" action="" style="flex:1 1 260px; display:flex; gap:8px; flex-direction:column;"> <input type="hidden" name="do" value="add_region"> <label>地区代码（如 CN-BJ / CN / US / --）</label> <input type="text" name="region" placeholder="CN-BJ" required> <label>对应源站/资源地址</label> <input type="url" name="origin" placeholder="https://bj.cdn.example.com" required> <button type="submit" class="btn btn-sm">添加映射</button> </form> </div> if (empty($regionMap)): ?> <p class="empty">暂无地区映射，请上方添加。</p> else: ?> <table class="table"> <thead> <tr><th style="width:22%;">地区</th><th>源站 / 资源地址</th><th style="width:16%;">操作</th></tr> </thead> <tbody> foreach ($regionMap as $region => $origin): ?> <tr> <td>echo htmlspecialchars($region); ?></td> <td>echo htmlspecialchars($origin); ?></td> <td> <form method="POST" action="" style="margin:0;display:inline;"> <input type="hidden" name="do" value="del_region"> <input type="hidden" name="region" value="echo htmlspecialchars($region); ?>"> <button type="submit" class="btn btn-danger btn-sm" onclick="return confirm('确定删除该地区映射吗？');">删除</button> </form> </td> </tr> endforeach; ?> </tbody> </table> endif; ?> <div class="hint">示例：CN-BJ → https://bj.origin.com；CN → https://cn.origin.com；-- → https://default.origin.com（兜底）。</div> </div> <!-- 卡片 3：地区判定测试 --> <div class="card"> <h2>🧪 地区判定测试</h2> <div class="grid2"> <div class="stat"><div class="v">echo htmlspecialchars($clientIp); ?></div><div class="l">当前访客 IP</div></div> <div class="stat"><div class="v">echo htmlspecialchars($detectRegion ?: '—'); ?></div><div class="l">检测地区</div></div> <div class="stat"><div class="v">echo htmlspecialchars($detectOrigin ?: '—'); ?></div><div class="l">匹配源站/资源</div></div> </div> <form method="GET" action="" style="margin-top:16px; display:flex; gap:8px; align-items:flex-end; flex-wrap:wrap;"> <input type="hidden" name="do" value="detect"> <label style="margin-bottom:0;">输入 IP 地址</label> <input type="text" name="ip" value="echo htmlspecialchars($detectIp); ?>" placeholder="例如 14.21.1.1" style="width:220px; margin-bottom:0;"> <button type="submit" class="btn btn-sm">判定地区</button> </form> if ($detectIp !== ''): ?> <div class="muted">IP <b>echo htmlspecialchars($detectIp); ?></b> 判定为地区 <b>echo htmlspecialchars($detectRegion ?: '未知(--)'); ?></b>，已echo ($detectRegion !== '' && $detectRegion !== '--') ? '记录命中' : '未记录'; ?>。</div> endif; ?> <div class="hint">判定依据：优先调用公网 IP 地理位置 API（ip-api.com），失败则返回未知；可在后台“地区映射”中手动补录。</div> </div> <!-- 卡片 4：回源连通性测试 --> <div class="card"> <h2>🔗 回源连通性测试</h2> <p class="muted">对源站/资源地址发送 HEAD 请求，探测是否可达及响应耗时。</p> <form method="GET" action="" style="margin-top:12px; display:flex; gap:8px; align-items:flex-end; flex-wrap:wrap;"> <input type="hidden" name="do" value="test_origin"> <label style="margin-bottom:0;">源站/资源 URL</label> <input type="url" name="url" value="echo htmlspecialchars($testUrl); ?>" placeholder="https://origin.example.com" style="width:360px; margin-bottom:0;"> <button type="submit" class="btn btn-sm">测试连通性</button> </form> if ($testUrl !== ''): ?> <div class="kv"><b>目标 URL：</b>echo htmlspecialchars($testUrl); ?></div> <div class="kv"><b>HTTP 状态：</b>echo $testStatus === null ? '—' : $testStatus; ?></div> <div class="kv"><b>响应耗时：</b>echo $testTimeMs === null ? '—' : $testTimeMs . ' ms'; ?></div> if ($testError): ?> <div class="msg warn">连通性测试失败：echo htmlspecialchars($testError); ?></div> elseif ($testStatus !== null): ?> <div class="msg ok">回源连通echo ($testStatus >= 200 && $testStatus < 400) ? '正常' : '异常'; ?>（状态 echo $testStatus; ?>）。</div> endif; <?php ?> <?php if (!empty($testHeaders)): ?> <div style="margin-top:10px;"><b>响应头摘要：</b></div> <pre>foreach ($testHeaders as $k => $v): echo htmlspecialchars($k) . ': ' . htmlspecialchars($v) . "\n"; endforeach; ?></pre> endif; <?php ?> <?php endif; ?> <div class="hint">建议测试“当前生效源站”以及各地区映射里的源站地址，确认回源链路畅通。</div> </div> <!-- 卡片 4.5：一键清理全部缓存 --> <div class="card" style="border: 2px solid #dc2626;"> <h2 style="color:#dc2626; display:flex; align-items:center; gap:8px;">🧹 一键清理全部缓存</h2> <p class="muted">清理 CDN 缓存目录下全部站点的 .cache 文件。清理后，所有站点首次访问将重新回源。</p> if (!empty($msg) && strpos($msg, '清理') !== false): ?> <div class="msg ok">echo htmlspecialchars($msg); ?></div> endif; ?> <form method="POST" action="" onsubmit="return confirm('确定要清理全部站点的 CDN 缓存吗？此操作不可恢复，清理后所有站点首次访问将重新回源。');"> <input type="hidden" name="do" value="clear_all_cache"> <button type="submit" class="btn btn-danger">一键清理全部缓存</button> </form> <div class="hint">缓存目录：stats/runtime-cache（或 config.php 中的 cache_dir）。操作会删除该目录下全部 .cache 文件，不影响源站数据。</div> </div> <!-- 卡片 5：地区命中记录 --> <div class="card"> <h2>📋 地区命中记录（最近 20 条）</h2> <p class="muted">记录首次访问某地区时的判定结果，下次同地区直接命中复用。</p> if (empty($hits)): ?> <p class="empty">暂无命中记录。</p> else: ?> <table class="table"> <thead> <tr><th style="width:20%;">时间</th><th style="width:20%;">地区</th><th style="width:30%;">访客 IP</th><th>对应源站/资源</th></tr> </thead> <tbody> foreach (array_reverse($hits) as $hit): ?> <tr> <td>echo htmlspecialchars($hit['time_str'] ?? ''); ?></td> <td><span class="badge echo ($hit['region'] ?? '') !== '--' ? 'badge-cdn' : 'badge-unk'; ?>">echo htmlspecialchars($hit['region'] ?? '--'); ?></span></td> <td>echo htmlspecialchars($hit['ip'] ?? ''); ?></td> <td>echo htmlspecialchars(\SimpleCdn\lib\Region::getRegionOrigin($hit['region'] ?? '') ?: '(未配置)'); ?></td> </tr> endforeach; ?> </tbody> </table> endif; ?> <div class="muted">记录持久化为 stats/region_hits.json，最多保留 200 条。</div> </div> </div> </body> </html>;